export function Header({
  title = "{{title}}",
  align = "{{align}}",
  bg = "{{bg}}",
  nav = {{nav}},
}) {
  const centered = align === "center";
  return (
    <header style={{
      display: "flex", alignItems: "center", justifyContent: centered ? "center" : "space-between",
      flexDirection: centered ? "column" : "row", gap: centered ? 8 : 0, textAlign: centered ? "center" : "left",
      fontFamily: "system-ui, sans-serif", fontSize: 14, color: "#241430", background: bg, padding: "12px 16px",
      borderBottom: "1px solid #24143018", boxSizing: "border-box",
    }}>
      <span style={{ fontWeight: 700, fontSize: 16 }}>{title}</span>
      {nav && (
        <nav style={{ display: "flex", gap: 18 }}>
          <a href="#" style={{ color: "#241430", textDecoration: "none", opacity: .75 }}>Product</a>
          <a href="#" style={{ color: "#241430", textDecoration: "none", opacity: .75 }}>Pricing</a>
          <a href="#" style={{ color: "#241430", textDecoration: "none", opacity: .75 }}>Docs</a>
        </nav>
      )}
    </header>
  );
}
